const fmt=n=>Number(n).toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});
const pct=(dados,p=.5)=>{const s=dados.toSorted((a,b)=>a-b);if(!s.length)return null;if(p===.5)return (s[Math.floor((s.length-1)/2)]+s[Math.floor(s.length/2)])/2;return s[Math.max(0,Math.ceil(s.length*p)-1)]};
const stats=a=>({n:a.length,mediana:pct(a.map(x=>x.segundos)),p95:pct(a.map(x=>x.segundos),.95),maximo:Math.max(...a.map(x=>x.segundos)),cliques:pct(a.map(x=>x.cliques))});
const nomes=[...new Set(final.resultados.map(r=>r.processo))];
const processos=nomes.map(processo=>({processo,desktop:stats(final.resultados.filter(r=>r.processo===processo&&!r.mobile)),celular:stats(final.resultados.filter(r=>r.processo===processo&&r.mobile))}));
const comparacao=[...new Set(antes.resultados.map(r=>r.processo))].map(processo=>{const a=stats(antes.resultados.filter(r=>r.processo===processo)),d=stats(depois.resultados.filter(r=>r.processo===processo));return{processo,antes:a,depois:d,variacaoPercentual:(d.mediana/a.mediana-1)*100}});
const resumoPublicado=[...new Set(publicado.resultados.map(r=>r.processo))].map(processo=>({processo,...stats(publicado.resultados.filter(r=>r.processo===processo))}));
