const arquivos=['src/pages/Clientes.tsx','src/services/clientes.ts','src/pages/Estoque.tsx','src/pages/Estoque.css','src/components/estoque/LinhaEstoque.tsx','src/components/ImportarCadastros.tsx'];
const hashes=[];for(const f of arquivos){const atual=await readFile(f),anterior=await readFile(resolve(pasta,'baseline-src',f.slice(4)));hashes.push({arquivo:f,antes:createHash('sha256').update(anterior).digest('hex'),depois:createHash('sha256').update(atual).digest('hex')})}
