const resumo={data:'2026-11-17',contagens,processos,comparacao,publicado:resumoPublicado,controlado,db,hashes,buildAntes:await ler('build-antes/health.json'),buildDepois:await ler('build-final/health.json'),publicadoNestaEntrega:false,falhaCorrigida:inicial.falhas};
